CREATE INDEX "IDX_PRODUCTS_CATEGORY" ON "PRODUCTS" ("CATEGORY" ASC);
CREATE UNIQUE INDEX "IDX_PRODUCTS_NAME" ON "PRODUCTS" ("NAME" ASC);
CREATE INDEX "IDX_PRODUCTS_PRICE" ON "PRODUCTS" ("PRICE" ASC);
ALTER TABLE "PRODUCTS" ADD CONSTRAINT "CHECK_NAME_LENGTH" CHECK (LENGTH(NAME) >= 3);
ALTER TABLE "PRODUCTS" ADD CONSTRAINT "CHECK_PRICE_POSITIVE" CHECK (PRICE > 0);
